package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.RuntimeIntStore;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.entity.AreaEffectCloud;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.*;
/** Molecular/tracer cloud sensor. Samples AreaEffectCloud concentration proxy with selectable sensitivity and a small sensor time constant. */
public class MolecularCloudReceiverBlock extends PassiveDirectionalSignalBlock{public static final IntegerProperty SENSITIVITY=IntegerProperty.create("sensitivity",0,3);private static final int[]GAIN={6,9,12,16};private static final String KEY="molecular_sensor";public MolecularCloudReceiverBlock(Properties p){super(p);registerDefaultState(defaultBlockState().setValue(SENSITIVITY,2));}@Override public MapCodec<MolecularCloudReceiverBlock> codec(){return RedstoneEngineering.MOLECULAR_CLOUD_RECEIVER_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){super.createBlockStateDefinition(b);b.add(SENSITIVITY);}private int raw(Level l,BlockPos p,BlockState s){var clouds=l.getEntitiesOfClass(AreaEffectCloud.class,new AABB(p).inflate(8.0));double c=0;for(var cloud:clouds)c+=Math.max(0.0,cloud.getRadius())/(1.0+cloud.distanceToSqr(p.getX()+.5,p.getY()+.5,p.getZ()+.5));return Math.min(15,(int)Math.round(c*GAIN[s.getValue(SENSITIVITY)]));}@Override protected int computeOutput(Level l,BlockPos p,BlockState s){return RuntimeIntStore.get(l,KEY,p,3)[0];}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)sl.scheduleTick(p,this,5);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){int[]rt=RuntimeIntStore.get(l,KEY,p,3);int target=raw(l,p,s);if(rt[0]<target)rt[0]++;else if(rt[0]>target)rt[0]--;rt[1]=target;rt[2]=Math.max(rt[2],rt[0]);updateOutput(l,p,s,rt[0]);l.scheduleTick(p,this,5);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){if(pl.isShiftKeyDown()){RuntimeIntStore.remove(l,KEY,p);updateOutput(l,p,s,0);pl.displayClientMessage(Component.literal("Molecular sensor history reset"),true);}else{int n=(s.getValue(SENSITIVITY)+1)%4;BlockState ns=s.setValue(SENSITIVITY,n);l.setBlock(p,ns,Block.UPDATE_CLIENTS);int[]rt=RuntimeIntStore.get(l,KEY,p,3);pl.displayClientMessage(Component.literal("Molecular receiver sensitivity="+n+" filtered="+rt[0]+" raw="+raw(l,p,ns)+" peak="+rt[2]+" | AreaEffectCloud concentration proxy"),true);}}return InteractionResult.sidedSuccess(l.isClientSide);}}
